
-- [[ Custom VM Layer | EXEC_CHUNK opcode = 186 ]]
-- Opcode table (randomized this run):
-- {'LOAD_K': 29, 'LOAD_ENV': 219, 'CALL': 149, 'RETURN': 142, 'JMP': 45, 'TEST': 57} ...
local EWvWqoF = "\151\255\165\120\46\216\88\161\251\103\130\48\20\29\103\43"
local LRsDsSRI = ""

local function wIbUxb(s)
  local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  local r = ""
  s = s:gsub("[^"..b.."=]","")
  for i = 1, #s, 4 do
    local a0,a1,a2,a3 = s:byte(i,i+3)
    local function bv(c) if not c then return 0 end; local p=b:find(string.char(c)) return p and p-1 or 0 end
    local n = bv(a0)*16777216 + bv(a1)*262144 + bv(a2)*4096 + bv(a3)*64
    -- fix: proper base64 decode
    local v0=bv(a0); local v1=bv(a1); local v2=bv(a2); local v3=bv(a3)
    local bits = v0*262144 + v1*4096 + v2*64 + v3
    r = r .. string.char(math.floor(bits/65536)%256)
    if a2 ~= string.byte("=") then r = r .. string.char(math.floor(bits/256)%256) end
    if a3 ~= string.byte("=") then r = r .. string.char(bits%256) end
  end
  return r
end

local function MMOvfz(enc_b64, key)
  local enc = wIbUxb(enc_b64)
  local out = ""
  local kl = #key
  for i = 1, #enc do
    out = out .. string.char(string.byte(enc,i) ~ string.byte(key, ((i-1)%kl)+1))
  end
  return out
end

local function VcOKRrWIZH(prog, key)
  -- VM dispatcher: read opcode, dispatch
  local op = prog[1]
  if op == 186 then
    -- EXEC_CHUNK: decrypt and execute the payload
    local src = MMOvfz(prog[2], key)
    local fn, err = load(src, "=(vm)", "t", _ENV or getfenv and getfenv() or _G)
    if not fn then error("VM load error: " .. tostring(err)) end
    return fn()
  end
  error("Unknown opcode: " .. tostring(op))
end

local NmxXwk = { 186, LRsDsSRI }
VcOKRrWIZH(NmxXwk, EWvWqoF)
